              'ជំហានទី ២ (Hypothesis)៖ សន្មតថារូបមន្តពិតចំពោះ $n = k$ គឺ $1 + 2 + ... + k = \\frac{k(k+1)}{2}$',
              'ជំហានទី ៣ (Induction)៖ យើងត្រូវបង្ហាញថាពិតចំពោះ $n = k+1$ គឺ $1 + 2 + ... + k + (k+1) = \\frac{(k+1)(k+2)}{2}$',
              '• អង្គខាងឆ្វេង $= [1 + 2 + ... + k] + (k+1) = \\frac{k(k+1)}{2} + (k+1)$',
              '• ដាក់ $(k+1)$ ជាកត្តារួម៖ $= (k+1)\\left(\\frac{k}{2} + 1\\right) = (k+1)\\left(\\frac{k+2}{2}\\right) = \\frac{(k+1)(k+2)}{2}$ (ពិត)',
              'សន្និដ្ឋាន៖ តាមគោលការណ៍អនុមានរួម រូបមន្តពិតចំពោះគ្រប់ $n \\ge 1$។'
