        <p><em>ចម្លើយ៖</em> ការរញ្ជួយដីកម្រិត ៧ បញ្ចេញថាមពលខ្លាំងជាងការរញ្ជួយដីកម្រិត ៥ រហូតដល់ <strong>១,០០០ ដង</strong>!</p>
